use Test;
use Red:api<2>;
my $*RED-DB = database "SQLite";


model Person {
    has Int $.id   is serial;
    has Str $.name is column is rw;
}

red-defaults “SQLite”;

;
Person.^create-table;

;
my $person = Person.^create(name => 'John');

;
Person.^create(name => 'John');

;
$person.name = 'John Doe';
$person.^save;

;
my $person2 = Person.new(name => 'Joan'); # ^create is not used
$person2.^save; # does INSERT, not UPDATE

;
Person.^create(name => "Paul"); # Method call with parentheses and an arrow pair
Person.^create: :name<Miki>;    # Colon form of method call is used

;
for Person.^all -> $person { say $person }

;
for Person.^all.grep(*.name.starts-with('Jo')) -> $person { say $person }

;
for Person.^all.grep(*.name.starts-with('Jo')).grep(*.id == 2) -> $person { say $person }

;
for Person.^all.grep({ $_.name.starts-with('Jo') && $_.id == 2}) -> $person { say $person }

;
is Person.^all.elems, 5, "all inserts persisted";
is Person.^load(1).name, 'John Doe', "setter saved";
is Person.^all.grep(*.name.starts-with('Jo')).elems, 3, "prefix filter";
throws-like { Person.^create }, Exception, "required name rejected";
is Person.^load(4).name, 'Paul', "load by ID";
throws-like { Person.^load(:name<Foo>) }, Exception, "non-key load rejected";
$person.^delete; is Person.^all.elems, 4, "delete one";
Person.^delete; is Person.^all.elems, 0, "delete all";
done-testing;

