use Test;
use Red:api<2>;
my $*RED-DB = database 'SQLite';
sub query(Str $sql, @bind = []) {
    my $statement = $*RED-DB.execute($sql, |@bind);
    my @rows;
    while my $row = $statement.row { @rows.push($row) }
    @rows
}
my @rows = query("CREATE TABLE b_b_b(\n   id integer NOT NULL primary key AUTOINCREMENT,\n   a1 varchar(255) NOT NULL ,\n   a2 varchar(255) NOT NULL ,\n   a3 varchar(255) NOT NULL ,\n   UNIQUE (a1, a2),\n   UNIQUE (a2),\n   UNIQUE (a2),\n   UNIQUE (a1, a2, a3)\n)\n");
$*RED-DB.execute("INSERT INTO b_b_b(a1,a2,a3) VALUES (?,?,?)", "a", "b", "c"); is query("SELECT count(*) AS n FROM b_b_b")[0]<n>, 1;
pass 'SQL excerpt executed';
done-testing;

